// Each runs the query page by page and calls fn with each batch of at most size rows.
func (q *LogRequestsQuery) Each(ctx context.Context, db *keel.DB, size int, fn func(ctx context.Context, batch []*supportlog.LogRequest) error) error {
	return keel.EachPtrs(ctx, db, &q.QueryCore, size, func(ctx context.Context, rows []unsafe.Pointer) error {
		return fn(ctx, *(*[]*supportlog.LogRequest)(unsafe.Pointer(&rows)))
	})
}

